function main() {
  const library = buildLibrary();
  const pack = buildPack(library);
  assert(pack.items.length === 400, 'AP Biology pack must contain 400 items.');
  assert(new Set(pack.items.map((item) => item.id)).size === 400, 'AP Biology item IDs must be unique.');
  assert(pack.domains.every((domain) => domain.itemCount >= 48), 'Every AP Biology unit must receive at least forty-eight pilot items.');
  assert(new Set(pack.items.map((item) => item.practiceId)).size === 6, 'All six AP Biology science practices must be represented.');
  assert(library.chapters.length === 8 && library.summary.richLessonPrototypes === 8, 'AP Biology library structured-lesson inventory is incorrect.');
  writeJson(packPath, pack);
  writeJson(libraryPath, library);
  console.log(`Built ${pack.id} ${pack.version} with ${pack.items.length} items across ${pack.domains.length} units and ${library.summary.richLessonPrototypes} rich lesson prototypes.`);
}

main();
